"Anyone remember why the sky is a portal?":"May nakaaalala ba kung bakit portal ang langit?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Sabi nila, kapag tumalon ka sa shaft, lalabas ka sa panig ng kaaway. Hindi ko susubukan.",
"The Swarm painted their visors red again. Show-offs.":"Pinintahan na naman ng Kawan na pula ang mga visor nila. Mga mayabang.",
"Ore, ore… when do we get some oil?":"Mineral, mineral… kailan kaya may langis?",
"I dreamt I was a toaster. It was peaceful.":"Napanaginipan kong toaster ako. Mapayapa.",
"Quiet. Too quiet.":"Tahimik. Sobrang tahimik.",
"See that? Our base is above the Swarm base again. Portals, man.":"Nakita n'yo? Nasa ibabaw na naman ng base ng Kawan ang base natin. Portal talaga.",
"Diman, if you're reading this — we need a vacation.":"Diman, kung binabasa mo ito — kailangan namin ng bakasyon.",
