"Autosaved":"Awtomatikong na-save",
"robot war · the sky is a portal":"digmaan ng mga robot · portal ang langit",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Maligayang pagdating sa bulalakaw! Isa kang combat robot ng Konsorsiyum. Lumingon gamit ang mouse at lumakad gamit ang WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: i-tap ang Shift para tumalon, hawakan ang Shift para lumipad. Nagre-recharge ang enerhiya sa lupa.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Magpaputok — kaliwang pindutan. Pakay — kanang pindutan: mas tumpak, may zoom. Magpaputok ng ilang beses.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Reload — R. Pinakamalakas ang bala sa katamtamang distansya, 20–50 metro.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Rocket — Q. Para sa mga tangke at gusali. Magpaputok ng rocket.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Sa itaas ang utos ng estratehista. Tumakbo sa mga berdeng palaso: may sprint ka sa ruta. Sakupin ang punto — manatili malapit sa beacon.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Sinasalo ka ng iyong iskuwad: nasa kaliwa ang mga larawan at kalusugan nila. Kung maiwan sila, hihilingin nilang maghintay ka.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — mabilis na palit ng yunit nang hindi umaalis sa laban: tumalon sa iskuwad o tangkeng pinakamalapit sa labanan. Subukan mo.",
"Next to a tank or turret press E to take control. Or just carry on.":"Kapag malapit ka sa tangke o turret, pindutin ang E para kontrolin ito. O magpatuloy ka lang.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Ngayon, estratehiya. I-tap ang \"◩ Estratehiya\" sa kanang itaas — tanaw mula sa itaas ng larangan ng labanan.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Ngayon, estratehiya. Pindutin ang {0} (o ang \"◩ Estratehiya\" sa kaliwang itaas) — tanaw mula sa itaas ng larangan ng labanan.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Sa estratehiya, tutulungan ka ng Gabay: sinasabi ng kahon sa itaas kung ano ang gagawin, ipinapakita ng balangkas ang button, at minamarkahan ng bilog ang lugar sa mapa. Tapusin ang tatlo sa mga payo nito.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Pumili ng iskuwad at i-tap ang berdeng \"▶ Pasukin\" na button — balik sa laban bilang sundalong iyon. Habang bumabaril ka, ang AI na estratehista ang namamahala sa hukbo.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Pumili ng iskuwad at pindutin ang {0} o ang berdeng \"▶ Pasukin\" — balik sa laban bilang sundalong iyon (kung walang napili — ang sarili mo). Habang bumabaril ka, ang AI na estratehista ang namamahala sa hukbo.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Tapos na ang pagsasanay! Sinisimulan na ng Kawan ang opensiba. Good luck, sundalo!",
