"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Pagkatapos, i-click (i-tap) ang lupa: lalakad sila at lalaban habang daan. Sa kaaway — atakihin ito. Katulad ng RMB.",
