"New in v6.2":"Bago sa v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Bagong itsura ng mineral: ang mga ugat ay kumikinang na hiwa-hiwang kristal na esmeralda sa itim na basalto na may mga kislap at berdeng ulap; ang Extractor ay hex na pedestal na may simbolong pukyutan at lattice na tore na may berdeng beacon sa tuktok (guhit at bandila sa kulay ng koponan)",
"New in v6.1":"Bago sa v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Piniling klase tulad ng sa Battlefield (U, mga numero pagkatapos mamatay): dito ka mag-respawn kung available",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Mga sasakyan sa first person (V — labas/kabina); banayad na aim assist — sa Mga Setting",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Madali nang lumabas sa ubod: Space — papunta sa shaft, B — kapsula papunta sa ibabaw; nare-reset ang mga epekto ng kakayahan kapag namatay",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Walang katapusang pag-unlad: mga heneral at Marshal ★, antas ng karera, mastery ng armas at attachment, mga medalya, pang-araw-araw na kontrata — screen ng Karera",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Estratehiya: maayos na zoom gamit ang gulong, mga icon at label sa ibabaw ng yunit (Alt — lahat), panel na \"Tropa / Gusali\" sa kaliwa",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"RMB — attack-move, dobleng RMB — martsa habang bumabaril; bihirang utos sa \"Iba pang utos ▾\"; walang dobleng button",
"New in v6":"Bago sa v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Baril na pang-shooter: hitscan na bala, riple na 720 RPM, MG, recoil, RMB na pag-aim, mga magasin at R na reload, hit marker",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Mas mabigat na grabidad, mabilis tumugon na jetpack, dash gamit ang Z o dobleng jet sa himpapawid; hindi na sumasama ang armas kapag lumilipat ng unit",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Mga builder: pumili ng builder, pumili ng gusali, ilagay ang blueprint; mga Extractor sa mga ugat ng ore; i-click ang \"ORE\" para makita ang kita at paano ito pabilisin",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Ang mga kulay-abong button ay nagpapaliwanag kung bakit at nag-aalok ng solusyon; mas malalaking button, bar na \"Isinasagawa\", \"▶ Possess\", Tab ang nag-iisang key ng mode",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera ng estratehiya na walang pagtalon o pagbaligtad, zoom papunta sa cursor, mahihila ang minimap",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Mga bagong sasakyan: raider na \"Jackal\", MLRS na \"Grad\" (mga rocket na naghahanap ng target), mortar na \"Hammer\"; ang Swarm ay may \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Hindi ginugulo ng AI strategist ang mga utos at hindi na nag-spam ng boses; ang labanan ay lumalapit sa iyo; B — redeploy, Shift+B — sa gitna ng laban; kompas, H — aling target",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Malayang laro (K) at solo (J), F2 na mga preset; Esc ay nagpo-pause at nagpapatuloy; mga save: slot, export at import",
"New in v5.3":"Bago sa v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Lipad: mas malakas ang grabidad malayo sa bulalakaw, C sa himpapawid ay preno, mas matalas ang liko ng thrust; hindi ka na \"nakabitin\" sa portal",
"New in v5":"Bago sa v5",
"Endless war by default and battle scale: normal, large, epic":"Walang katapusang digmaan bilang default at laki ng laban: karaniwan, malaki, epiko",
"Save and load the battle (autosave every 3 minutes)":"I-save at i-load ang laban (autosave kada 3 minuto)",
"Squadmates with callsigns: portraits, health and live chatter":"Mga kasamahan sa squad na may callsign: mga larawan, kalusugan at buhay na usapan",
"Fog of war in strategy, friends and foes outlined differently":"Fog of war sa estratehiya, magkaiba ang highlight ng kakampi at kaaway",
"Camera fly-over when switching, portal aurora instead of rings":"Lipad ng kamera sa paglipat, aurora ng portal sa halip na mga singsing",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Mga gawaing pangalawa, shortcut sa kalangitan, mga tirahan ng unang ekspedisyon na may suplay, mga kristal, yelo sa bunganga, mga bagyo ng alikabok",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Pagsasanay, cinema mode na may pag-record ng video, mga escort na sasakyan mula sa AI strategist",
