"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Granada: pindutin nang matagal ang G — makikita ang arko at bilog ng pagsabog; i-drag ang daliri sa button — anggulo; bitawan — ihagis.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Granada: pindutin nang matagal ang {0} para sa arko at bilog ng pagsabog, bitawan para ihagis. Layo — sa anggulo ng tingin, gulong — lakas, RMB — sa paanan.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Mga granada: pindutin nang matagal ang G para sa arko ng lipad, punto at radius ng pagsabog, distansya; bitawan para ihagis. Layo sa anggulo ng tingin, gulong — lakas, RMB — sa paanan",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Tumatalbog ang granada at gumugulong sa dalisdis, sabog sa 2.5 s; 2 granada, 9 s na recharge; icon na babala para sa granada ng kaaway sa malapit",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Granada: pindutin nang matagal — arko at punto ng pagsabog, bitawan — ihagis · overdrive ng tangke",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — pindutin nang matagal: makikita ang arko at bilog ng pagsabog, bitawan para ihagis. Sabog sa 2.5 s, 2 granada.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granada ({0}): pindutin nang matagal — arko ng lipad, punto at radius ng pagsabog, distansya; bitawan — ihagis; ang mabilis na pindot ay agad na hahagis. Layo sa anggulo ng tingin, gulong — lakas, RMB — sa paanan. Telepono: pindutin nang matagal ang G at i-drag ang daliri.",
