"The Polygon works in developer mode only":"Gumagana lang ang Polygon sa developer mode",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Polygon: walang katapusang laban sa gitna ng mapa na may palakas. X — angkinin ang sundalo roon",
