"Tap \"Aim\" to zoom in. Tap again to zoom out.":"I-tap ang \"Tutok\" para mag-zoom in. I-tap ulit para mag-zoom out.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Sumusunod sa iyo ang iskuwad mo. Buksan ang ☰ → \"Pause\" → ang tile na \"Kasama ko ang iskuwad\" — magiging \"Mag-isa\".",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Napili ang inhinyero — i-tap ang \"◆ Magmina ng kristal\" sa card nito sa ibaba (o i-tap ang berdeng kristal).",
"Training complete!":"Tapos na ang pagsasanay!",
"steps":"hakbang",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Marunong ka nang magtayo ng base, mag-utos ng tropa, mamuno at lumipat sa laban. Susunod — totoong laban: tutulong ang Tagapatnubay habang naglalaro ka.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Marunong ka nang gumalaw, lumipad, bumaril, magtago at mamuno ng iskuwad. Susunod — totoong laban.",
"Real battle":"Totoong laban",
"Again":"Ulitin",
"done":"tapos na",
"you are on PC: keyboard and mouse":"PC ang gamit mo: keyboard at mouse",
"you are on a phone: touch screen":"telepono ang gamit mo: touch screen",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Ligtas na sandbox: mga dummy lang ang kalaban, walang babaril sa iyo. Mabibilang lang ang hakbang kapag ikaw mismo ang gumawa ng aksyon.",
"Show others (training for the other device)":"Ipakita ang iba (pagsasanay para sa ibang device)",
"Old training (v7.1)":"Lumang pagsasanay (v7.1)",
"Back to the normal device mode":"Ibalik sa normal na mode ng device",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Ang pagsasanay para sa ibang device ay magre-reload ng page sa mode nito (PC — mouse at keyboard, telepono — touch; sa PC, madaling subukan ang touch sa Chrome: F12 → icon ng telepono).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Pagsasanay ×4: magkakahiwalay na hakbang-hakbang na aralin ng \"Estratehista\" at \"Tagabaril\" para sa PC at para sa telepono. Ligtas na sandbox na may mga dummy, naka-highlight ang tamang button, mga palaso, animated na key, mouse at galaw; bibilangin lang ang hakbang kapag totoong aksyon ang ginawa, \"ulitin ang hakbang\", progreso sa itaas at gantimpala sa dulo",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Ipinapakita ng menu ng Pagsasanay ang mga aralin para sa device mo; \"Ipakita ang iba\" — lahat ng apat sa kahit anong device; nariyan pa rin ang \"Lumang pagsasanay (v7.1)\"",
"New in v7.2":"Bago sa v7.2",
"NEW IN v7.2":"BAGO SA v7.2",
"No grenades left":"Naubos na ang granada",
"Rocket and grenade recharging · {0} s":"Nagcha-charge ang rocket at granada · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Kaliwa — galaw, kanan — tingin · tap sa kaaway — rocket / granada · 2 tap — reflex · 3 tap — atake ng artilerya",
"Less":"Mas kaunti",
"More":"Mas marami",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"May sasakyan o istruktura ng kaaway sa malapit — i-tap ito: lilipad ang rocket.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Maraming kalaban — mag-double tap sa walang laman na bahagi sa kanan: babagalan ng reflex ang oras.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Itutok sa grupo ng kaaway at mag-tap ng 3 beses — atake ng artilerya.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Kaliwang hinlalaki — galaw, kanan — tingin. Kusang bumaril kapag nakatutok sa kaaway.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ sa kaliwang gilid — jetpack: mag-tap para tumalon, hawakan para lumipad.",
"Old v7.2 layout":"Lumang layout ng v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"I-drag ang daliri sa kanang kalahati ng screen — may lalabas na look stick sa ilalim nito.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Hawakan ang kaliwang bahagi at mag-slide — may lalabas na stick sa ilalim ng daliri mo. Abutin ang berdeng marka.",
"Hold the \"Jet\" button at the left edge.":"Hawakan ang button na \"Jet\" sa kaliwang gilid.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Itutok sa manekin gamit ang kanang stick — kusang bumabaril ang sundalo mo kapag nasa target ang crosshair.",
"Tap the dummy on the screen — a rocket flies.":"I-tap ang manekin sa screen — lilipad ang rocket.",
"Tap the dummy — a grenade flies in an arc, right at it.":"I-tap ang manekin — lilipad ang granada nang paarko, diretso rito.",
"Double tap an empty spot on the right quickly.":"Mabilis na mag-double tap sa walang laman na bahagi sa kanan.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lite mode para sa mahihinang telepono: mas mababang resolusyon, walang anino o distortion, kalahati ng bot at particle, hanggang 30 FPS lang; kusang ibinababa ang resolusyon kapag FPS < 25. Naka-on bilang default sa telepono (Mga Setting → Grapiko → \"Lite mode\"; o ?lite=1 / ?lite=0 sa link).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telepono: bagong kontrol. Kaliwa — galaw, kanan — tingin (parehong stick ay lumalabas sa ilalim ng daliri). Kaliwang hinlalaki lang — \"auto\"; kapag gamit ang kanan, kusang bumabaril ang sundalo kapag nasa kaaway ang crosshair. Tap sa kaaway — rocket o granada, 2 tap — reflex, 3 tap — atake ng artilerya. Kusang reload. Jetpack — button sa kaliwang gilid. Libre ang mga ibabang sulok, minimap sa sulok, maisasara ang mga hint gamit ang krus, maititiklop ang layunin. Lumang layout: Mga Setting → Telepono.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Mga hint (pop-up at Kurator) — iisang switch sa mga setting. Kung sino ang nilalaro mo (uri ng sundalo o sasakyan) — label na \"Ikaw: …\" sa HUD. Transparent ang optics ng riple at MG. Naka-dock sa kanan ang panel na \"Arsenal\", maitiklop at maisara. Inalis ang \"Mag-isa nang walang iskuwad\" (J). Hindi na inuulit ng boses ng AI strategist ang parehong linya. May indicator ng turret laban sa katawan ang mga tangke. Hindi na naglalaho ang cursor sa simula ng pagsasanay sa estratehiya.",
