"Possess vehicles and drones":"Possess ng mga sasakyan at drone",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"Sa kanyon: {0}. AI ang nagmamaneho, ikaw ang bumabaril. {1} — bumaba",
"The vehicle is destroyed — you jumped off":"Wasak ang sasakyan — tumalon ka palabas",
