"Strategist: troopers dropping to you — +{0} (−{1} ore)":"AI strategist: bumababa sa iyo ang mga sundalo — +{0} (−{1} mineral)",
"Hold on, sending troopers your way":"Kapit lang, nagpapadala ako ng mga sundalo sa iyo",
