"Voice of hints and curator":"Boses ng mga hint at Kurator",
"Advanced: custom class order":"Advanced: sariling ayos ng mga klase",
"Voice of hints & curator":"Boses ng mga hint at Kurator",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telepono: tatlong mode ng stick. Kaliwa lang — \"auto\" (malakas na magnet, mas mahina ang bala). Kanan lang — kusang bubukas ang pagtutok, mas malakas na magnet, mas tumpak. Pareho — walang pagtutok, mas mahina ang magnet at katumpakan. Itinatago/ibinabalik ng button na 👁 sa kanan ang HUD.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telepono: pinasimple ang estratehiya — builder at mga gusali lang. Mga card sa kaliwa (builder, HQ, kuwartel…): tap — lilipad ang camera roon, ipinapakita ng ibabang bar kung ano ang itatayo/gagawin. \"Sa laban\" — kaliwang itaas. Kusang lumalaban ang hukbo. Buong estratehiya — Mga Setting → Telepono.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Possess — dalawang switch: \"Mga iskuwad\" at \"Mga sasakyan\" (naka-off ang mga sasakyan bilang default sa telepono — AI ang nagmamaneho). Kapag naka-off ang mga sasakyan, E (telepono: button sa kanan) sa tabi ng sasakyang kakampi — hawakan ang kanyon nito: kusa itong umaandar, ikaw ang bumabaril. Nasa \"Advanced\" ang lumang sariling ayos ng klase. Sumasagot sa radyo ang yunit kapag pina-possess mo.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Matatalinong hint: kusang namamatay ang mga pangunahing hint pagkatapos ng ika-2 launch, pero ituturo pa rin ng laro ang feature na hindi mo pa nagagamit. Mga switch: pangunahin / advanced / bihira, at hiwalay para sa boses ng mga hint at Kurator.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Nagcha-charge ang reflex mula sa mga napatay (mas malakas ang serye). Naiwan o namatay ang mga kakampi — magbababa ang estratehista ng bago sa iyo (mas mahal kaysa karaniwang reinforcement). Isinama na ang grapiko at tunog ng v7.2gfx: mga pagsabog na pumapaimbulog, usok, labi, akustika ng mga shaft at crater. Totoo na ang petsa ng build.",
