"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Portal ang langit: kapag lumipad ka pataas, lalabas ka sa kabilang panig ng bulalakaw.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"Sundin ang mga utos ng estratehista — doble at triple ang XP para sa kanila.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — agad lumipat sa iskuwad o sasakyang pinakamalapit sa labanan.",
"Bullets hit hardest at medium range, 20–50 meters.":"Pinakamalakas ang tama ng bala sa katamtamang distansya, 20–50 metro.",
