"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Hindi nagbabago ang Karera at mga save. Sa laban, ang parehong menu ay ang button na \"🛠 Menu\" sa kanang itaas{0}.",
"New developer match":"Bagong laban ng developer",
"all unlocked, endless ore, instant build, arsenal":"lahat bukas, walang katapusang mineral, agarang pagtatayo, arsenal",
"Trainings — all 4":"Mga pagsasanay — lahat ng 4",
"PC and phone (strategy and shooter)":"PC at telepono (estratehiya at tagabaril)",
