"Cinema: everything built":"Sine: lahat naitayo",
"both bases built and upgraded — for footage":"parehong base ay naitayo at napalakas — para sa footage",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Cinema mode — split screen: bot na estratehista sa kaliwa (tanaw mula sa itaas ng base at hukbo), bot na tagabaril sa kanan sa first person. Mga button sa ibaba (mga key S, P): \"Split screen\" at \"★ Lahat naitayo\" — parehong base ay naitayo at napalakas para sa footage.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Wala na ang ubod at ang mga tunel sa buong bulalakaw — buo na ang bulalakaw, sa ibabaw na lang ang laban.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telepono: itinatago ng 👁 ang HUD pero nananatili ang jetpack, ⇆, ang mga stick at ang marker ng misyon. Ang \"◎ Aim\" (kanang daliri lang) — mas malakas at mas malawak na magnet; ang magnet para sa tatlong mode — Mga Setting → Kontrol → \"Advanced\". Sa kanyon ng sasakyan, \"Bumaba\" ang nakasulat sa button.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Pagsasanay: sa telepono, pagsasanay para sa telepono lang; sa PC, pang-PC lang. Lahat ng 4 ay nasa menu na \"🛠 Developer\". Iisang menu na ang Developer mode at ang Arsenal (sa laban — \"🛠 Menu\" sa itaas na kanan, F8 sa PC).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Mga estilo ng grapiko na \"Dendy (8-bit)\" at \"16-bit\": Mga Setting → Grapiko → \"Estilo ng grapiko\" (detalye — ang ⚙ button). Kung mas mababa sa 24 ang FPS sa unang ~10 s ng laban, kusang bubukas ang Dendy (kung mas mababa pa sa 20 — mas malalaking pixel, 120 linya); ang abiso na \"ibalik sa normal\" ay permanenteng magbabalik ng normal na grapiko. Ang pinili mo sa menu ang laging masusunod.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Mga 3D model ng kapaligiran (guho, wasak na makina, kuta) — yaong mataas lang ang rating, kusang nilo-load kapag kailangan. Para i-off: Mga Setting → Grapiko → \"Mga bagong 3D model ng kapaligiran\".",
"New in v7.5":"Bago sa v7.5",
"NEW IN v7.5":"BAGO SA v7.5",
"Built by the squad: {0}":"Itinayo ng iskuwad: {0}",
"Trooper, the engineers are busy — help finish the {0}, {1} m. {2} at the site.":"Trooper, abala ang mga builder — tulungan mong tapusin ang {0}, {1} m. {2} sa lugar ng konstruksiyon.",
"Strategist order: finish the {0} ({1} m)":"Utos ng estratehista: tapusin ang {0} ({1} m)",
"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"Estratehista: marka ⌖ sa kumpol ng kaaway, {0} m — atake ng artilerya sa loob ng 8 segundo. Lumayo ka!",
