"STRATEGIST'S MARK":"MARKA NG ESTRATEHISTA",
"BUILD SITE":"LUGAR NG KONSTRUKSIYON",
"cache":"taguan",
" m":" m",
"button — stop":"button — tigil",
"— stop":"— tigil",
"PRONE · crawling · Ctrl — stand up":"DAPA · gumagapang · Ctrl — tumayo",
"stop building":"itigil ang pagtatayo",
"cache: take the weapons":"taguan: kunin ang mga armas",
"Building: {0} — stay close":"Nagtatayo ka: {0} — manatili sa malapit",
"Prone / stand up (crawl)":"Dumapa / tumayo (gumapang)",
"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Puwedeng magtayo ang mga trooper: E (sa telepono \"Enter\") sa sarili mong lugar ng konstruksiyon — ang trooper mo ang magtatayo, tutulong ang mga kasamahan sa malapit. Kung abala ang mga builder, hihingi ng tulong sa iyo ang estratehista — marka na \"LUGAR NG KONSTRUKSIYON\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Mga marka ng estratehista: naglalagay ang estratehista ng ⌖ sa kumpol ng kaaway malapit sa iyo — tatamaan ito ng artilerya pagkalipas ng 8 s at magsa-salvo ang mga kalapit na kakampi na \"Grad\" MLRS. Ang sarili mong atake ng artilerya mula sa mode na estratehiya ay may suporta rin ng \"Grad\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Mga taguan ng armas sa mga cargo container at bumagsak na satellite (📦 nakikita mula sa 70 m): E — mabigat na machine gun sa loob ng 90 s, incendiary na bala o rocket, at punong mga granada. Paggapang: Ctrl — dumapa / tumayo (mas mababa, mas matatag, mas tumpak ang tutok, pero mabagal).",
"Anonymous statistics":"Anonymous na estadistika",
"no names or emails: version, device, play time — to make the game better":"walang pangalan o email: bersyon, device, oras ng paglalaro — para mapabuti ang laro",
"Anonymous statistics (no names or emails)":"Anonymous na estadistika (walang pangalan o email)",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"Split-screen na sinehan, walang core at tunel, nagtatayo ang mga sundalo, mga marka ng estratehista, mga taguan, paggapang, menu ng developer",
