"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Maglaro na\" — ang unang button ng menu: maikling paglipad sa ilalim ng langit na portal at diretso sa laban (laktawan gamit ang anumang key o tap).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Ramdam ang mga tama: metalikong tunog at mga kislap, marker ng pagpatay sa crosshair (headshot — dilaw), serye na ×N, banayad na yanig mula sa mga pagsabog, slow motion sa mahahalagang pagpatay. Puwedeng i-off sa Mga Setting ang yanig, slow motion at pahiwatig.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Resulta ng laban: oras, mga pagpatay, pinakamahabang serye, ★ MVP at pinakamahusay na iskuwad, card ng laban — \"⇪ Ibahagi\", PNG o link sa laro.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Pahiwatig na \"ano ang gagawin ngayon\" sa kaliwa sa ilalim ng mga resource: utos ng estratehista, punto ng pagsakop, pag-atake ng Swarm. ✕ o F7 — itiklop.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Kusang nagse-save ang laban kapag isinara o itinago ang tab — \"⟲ Magpatuloy\" sa menu.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Nananatili ang v7.5 sa menu na \"🕘 Bersyon ng laro\" kung sakaling mas gusto mo ito. Ipinapadala na ngayon ang anonymous na estadistika (walang pangalan o e-mail); i-off sa Mga Setting.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Maglaro na\", tugon sa mga tama, resulta ng laban na may share card, pahiwatig na \"ano ang gagawin\", autosave",
"and older: v7.5, v7.4, milestones v1–v7.0":"at mas luma: v7.5, v7.4, mga mahalagang bersyon v1–v7.0",
"New in v7.6":"Bago sa v7.6",
"NEW IN v7.6":"BAGO SA v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Pumili ng paksiyon bago ang laban: ang \"Consortium\" (mabigat na impanterya na may power armor, baluti at artilerya) o ang \"Swarm\" (bilis, mga kawan ng drone, mabibigat na putok na may distortion). Ang AI ang maglalaro sa kabila. Natatandaan ang pinili mo.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"May sariling sasakyan at natatangi ang bawat paksiyon: sa Consortium — ang tangkeng \"Rinoceronte\" at \"Mga plakang ceramite\", sa Swarm — ang \"Kawan ng drone\" at \"Mga phase jetpack\". Sinuri ang balanse sa mga laban ng mga bot.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Mga bunganga ng pagsabog: ang artilerya, mga rocket at kanyon ng tangke ay naghuhukay ng mga hukay sa bulalakaw — puwede kang maglakad at magmaneho sa mga ito at magkubli sa loob.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Third-person view para sa sundalo (V, naaalala; sa phone — Controls) at maayos na camera ng sasakyan na may marka kung saan tatama ang kanyon.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Nasa menu na \"🕘 Bersyon ng laro\" pa rin ang v7.6 kung mas gusto mo ito.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Mga paksiyon ng Consortium / Swarm na mapipili bago ang laban, mga bunganga ng pagsabog, third-person view",
"and older: v7.6, v7.5, milestones v1–v7.0":"at mas luma: v7.6, v7.5, mga milestone v1–v7.0",
