"Anomaly ahead! The vein is singing — go around!":"May anomalya sa unahan! Umaawit ang ugat — umiwas tayo!",
"Hear that hum? A singing vein. Keep clear!":"Naririnig mo ba ang ugong? Umaawit na Ugat. Huwag lumapit!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalya! Umiikot ang hangin — Alimpuyo ito, umiwas ka!",
"Rocks floating in the air… A whirlpool! Stay out!":"Nakalutang sa hangin ang mga bato… Alimpuyo! Huwag kang lumapit!",
"Anomaly ahead — it is crackling with current!":"May anomalya sa unahan — kumakaluskos sa kuryente!",
"Rods and lightning — a Crackler. It loves armour!":"Mga tulos at kidlat — Kaluskos. Mahilig siya sa armor!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalya! Nanginginig ang lupa sa init — Bagang!",
"Careful, a Brazier underfoot!":"Ingat, may Bagang sa ilalim ng paa mo!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalya — berdeng ulap! Asido, pigil-hininga!",
"The mist is drifting our way, go around!":"Gumagapang papunta sa atin ang ulap, umiwas tayo!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalya! Parang salamin ang hangin — Lente, bumabaluktot ang mga bala!",
"Everything is warping… a Lens nearby!":"Nagbabago ang lahat ng hitsura… may Lente sa malapit!",
"Ha! An enemy walked right into the anomaly!":"Ha! Pumasok mismo ang kaaway sa anomalya!",
"Got him! Lure them into anomalies!":"Huli ka! Akitin sila papunta sa mga anomalya!",
"Beautiful zap! One less tin can.":"Ganda ng tama! Bawas na isang lata.",
"The anomaly got me!":"Tinamaan ako ng anomalya!",
"Ow! Don't go in there!":"Aray! Huwag kayong pumasok diyan!",
"Discharged! It is dormant now.":"Nawalan ng bisa! Tulog na ito ngayon.",
"Clear, the anomaly is discharged.":"Ligtas na, nawalan ng bisa ang anomalya.",
"They say veins hide artifacts. Only first the vein sings…":"Sabi nila, may mga artifact na nakatago sa mga ugat. Pero umaawit muna ang ugat…",
"Throw a bolt first, then walk. Old habit.":"Maghagis ka muna ng bolt, saka lumakad. Dating kaugalian.",
