"Supply drop":"Supply drop",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Nagbabagsak ng kahon malapit sa mga puwersa mo: bala, granada, rocket, piyesa ng armas, repair kit.",
"\"Grad\" rocket strike":"Atake ng rocket ng \"Grad\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 na rocket sa malawak na lugar pagkalipas ng 3 segundo — mas mabilis at mas malawak kaysa sa artilerya.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Suporta: kahon, pagsisiyasat, \"Grad\", atake ng artilerya (tapos 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"BABALA: paparating ang \"Grad\" ng Swarm sa lugar ninyo!",
"Warning! Rocket salvo on our position!":"Babala! Salvo ng rocket sa posisyon natin!",
"take the supply crate":"kunin ang kahon ng suplay",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Mga anomalya sa bulalakaw (alon 1): ang \"Umaawit na Ugat\" — kumikinang na berdeng kristal na umuugong at tumatama ng mga ritmikong pulso sa lahat ng nasa paligid; ang \"Alimpuyo\" ay humihila at humahampas, ang \"Kaluskos\" ay nagpapakawala ng kuryente sa pagitan ng mga tulos, ang \"Bagang\" ay sumisiklab sa ilalim ng paa, at ang \"Maasim na ulap\" at ang \"Lente\" (nagbabaluktot ng mga bala at ng tanaw mo) ay lumilibot.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Madarama mo ang mga anomalya nang maaga (ugong, kislap, alimuom). Para mawalan ng bisa ang isa, gumamit ng granada, rocket o bolt (E malapit dito): matutulog ito at minsan ay mag-iiwan ng artifact na may plus at minus. Nagbababala ang iskuwad mo sa radyo, at kung minsan ay napapasok ng mga kaaway (at kakampi) ang mga ito — akitin sila!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Suporta kapalit ng command points: 4 sa laban (📡 sa phone) — supply drop, pag-scan ng pagsisiyasat, atake ng rocket ng \"Grad\", artilerya sa crosshair. Nakikita lang ng strategist ang mga anomalya sa mapa pagkatapos ng scan.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Mga kahon ng suplay sa mga guho ng lumang ekspedisyon, malapit sa mga HQ at sa tabi ng mga natapos na gusali: bala, granada, rocket, piyesa ng armas (nagbubukas ang mga ito ng attachment).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Nasa menu na \"🕘 Bersyon ng laro\" pa rin ang v7.7. Puwedeng patayin ang mga anomalya sa Mga Setting.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Mga anomalya (ang \"Singing Vein\" at 5 pa), pag-alis ng bisa gamit ang bolt at granada, mga artifact, tawag ng suporta kapalit ng PK, mga kahon ng suplay",
"and older: v7.7, v7.6, milestones v1–v7.0":"at mas luma: v7.7, v7.6, mga milestone v1–v7.0",
"New in v7.8":"Bago sa v7.8",
"NEW IN v7.8":"BAGO SA v7.8",
"Close":"Isara",
"Anomalies on the meteor":"Mga anomalya sa meteor",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"Ang ☰ sa sulok ay nagbubukas ng pause menu: Magpatuloy, Ulitin, Pagsasanay, Grapiko, Mga Setting, Pangunahing menu (may kumpirmasyon). Phone: ☰ sa kanang itaas (mga aksyon sa laban — ang tile na \"⚡ Mga Aksyon\"); PC: ang button na \"☰ Menu\" sa kanang itaas o Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Laging normal ang grapiko bilang default — Dendy lang kung piliin mo: ang switch na \"Grapiko: Normal / Dendy (8-bit) / 16-bit\" ay nasa mismong pangunahing menu at pause menu. Kapag matindi ang lag ng laro, lalabas ang tip na may button na \"I-on ang Dendy\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Phone at tablet: lalabas lang ang action button na \"✋\" sa kanan kapag may magagawa sa malapit — \"Kunin\" (taguan, kahon), \"Sumakay\" (sasakyan, turret, kanyon), \"Magtayo\", \"Bumaba\", \"Bolt\" sa anomalya. Puwede mo ring i-tap ang naka-highlight na bagay.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Phone, estratehiya: idiin ang daliri nang ~0.3 s (mag-vibrate ang phone, lalabas ang dilaw na singsing) at i-drag — kahon ng pagpili; ang karaniwang swipe ay gumagalaw sa camera. May button ding \"Kahon\" sa kanan; sa pagsasanay, tinatanggap din ng hakbang na \"Kahon\" ang pag-tap sa iskuwad.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Phone: mas madaling pindutin ang maliliit na button, mas malaki ang listahan ng suporta 📡, hindi na tinatakpan ng mga panel ng estratehiya ang pause at mga resulta. Nasa menu na \"🕘 Bersyon ng laro\" pa rin ang v7.8.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menu ☰ sa phone at PC, walang auto-Dendy, button na \"✋\" sa touch, pagpili gamit ang kahon sa phone",
