"Pause: resume, restart, training, graphics, settings, main menu":"Pause: magpatuloy, ulitin, pagsasanay, grapiko, mga setting, pangunahing menu",
"Menu: pause, restart, training, graphics, settings":"Menu: pause, ulitin, pagsasanay, grapiko, mga setting",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Idiin ang daliri sa lupa nang ~0.3 s — mag-vibrate ang phone at lalabas ang dilaw na singsing — tapos, nang hindi binibitawan, i-drag: lalabas ang kahon ng pagpili. O gamitin ang button na \"Kahon\" sa kanan. Gumagana rin ang simpleng pag-tap sa iskuwad.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Para sa full screen sa iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — bubukas ang laro nang walang mga bar ng Safari.",
"Open portal-meteor.pages.dev for that.":"Buksan ang portal-meteor.pages.dev para rito.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Tap — pumili · tap sa lupa — lumakad · pindutin nang matagal — menu ng utos · pindutin nang matagal at i-drag — kahon · 2 daliri — zoom",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Bayaning assassin: mga blink-dash, katana, shuriken. Kusang tumatalon sa mga sona ng kaaway at hinihiwa ang mga robot. 1 bawat panig.",
"Shadow protocol":"Protokol na \"Anino\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Pananaliksik: ina-unlock ang robo-ninja sa Kuwartel. Kailangan ng natapos na pabrika ng mech.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Bayani (1 bawat panig): kusang nagte-teleport sa mga sona ng kaaway at hinihiwa ang mga robot; Angkinin siya para maglaro nang mano-mano.",
