"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DUWELO NG NINJA! Mag-block bago tumama para i-parry, mag-blink para umiwas. Bantayan ang kislap ng paghahanda",
"The two ninjas have met in a duel!":"Nagkita na ang dalawang ninja sa duwelo!",
