"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: kusa siyang tumatalon sa mga sona ng kaaway at humihiwa. Ang joystick / WASD ay nagpapahinto rito nang 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Mano-mano: i-tap ang kaaway — dash at hiwa, swipe — hataw, 🛡 — block",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Mano-mano: kaliwang pindutan — katana, kanang pindutan — block, Shift — blink, Q — shuriken, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: mag-tap sa kaaway — dash at hiwa, swipe sa kanan — taga, ● — atake, 🛡 — harang (tamang oras = parry), ⇑ — blink, ✦ — mga shuriken, ◎ — teleport, AUTO — siya na ang bahala",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: kaliwang pindutan — katana (hawakan — mabigat na hiwa), kanang pindutan — harang (tamang oras = parry), Shift/Z — blink, Q — mga shuriken, G — teleport sa crosshair, talon sa ere — double jump / wall-run, {0} — AUTO",
