"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: mahigit 100 track ni EDMITRY sa mismong laro — ang pindutang 📻 (PC: key 5, [ ] — track). Naka-stream ang musika kapag kailangan at hindi nagpapabigat sa laro; lakas ng tunog at autostart sa Mga Setting, may link na \"Pakinggan sa Spotify\".",
