"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY): lakas ng tunog",
"Radio: start by itself in battle":"Radio: kusang mag-on sa laban",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: isang cyborg na may katana. Nabubuksan sa Kuwartel sa pananaliksik na \"Shadow Protocol\" (kailangan ng Mech Factory). Kusa siyang nagte-teleport sa mga sona ng kaaway, hinihiwa-hiwa ang mga kaaway (walang dugo — mga kislap), may dash, shuriken, at duelo laban sa ninja ng kaaway. I-possess siya — AUTO mode o manwal na kontrol (may sariling mga pindutan sa telepono).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 track ni EDMITRY sa mismong laro. Key 5 (mababago), sa telepono — ☰ → Mga Setting → Tunog. Lakas ng tunog at \"kusang mag-on sa laban\" ay nasa mga setting; humihina ang musika kapag may pagsabog at boses sa radyo.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Mga bagong wika: Uzbek at Tajik — kumpleto; Chinese, Spanish, Portuguese — bahagya. Bagong pamili ng wika sa menu sa tabi ng \"Bagong laban\".",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telepono: ang \"itago ang mga icon\" 👁 ay nag-iipon ng natitirang mga pindutan sa maayos na hanay sa kanang gilid; hindi na nagpapatong-patong ang portrait; iPhone — hindi na kalaban ng laro ang mga galaw ng Safari, at ang \"Share → Add to Home Screen\" ay nagbubukas nito nang buong screen.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Mula sa v7.8.1: ☰ menu sa sulok (pause, ulitin, pagsasanay, grapiko), walang auto-Dendy, ✋ na pindutan ng aksyon sa telepono. Nananatili ang v7.8.1 at v7.8 sa menu na \"🕘 Bersyon ng laro\".",
