"Enemies bunched up — {0}: grenade":"Nagkumpol ang mga kaaway — {0}: granada",
"Enemy cluster — {0}: strike at your aim":"Kumpol ng kaaway — {0}: atake sa target mo",
"Goal: destroy the enemy HQ and all its key buildings":"Layunin: wasakin ang HQ ng kaaway at lahat ng pangunahing gusali nito",
"60 minutes: destroy the enemy HQ or hold more points":"60 minuto: wasakin ang HQ ng kaaway o hawakan ang mas maraming punto",
"Left thumb — move, right — look, red — fire":"Kaliwang daliri — galaw, kanan — tingin, pula — putok",
"Mode button at the top right: tap — next, hold — pick":"Mode button sa kanang itaas: tap — susunod, pindutin nang matagal — pumili",
"⇆ — next unit · ☰ — menu, clean screen, this card":"⇆ — palitan ang sundalo · ☰ — menu, malinis na screen, gabay na ito",
