"Hero quest":"Quest mula sa bayani",
"Commander, their AA radar blinds our air. Take it down.":"Komandante, binubulag ng AA radar nila ang hukbong panghimpapawid natin. Wasakin mo.",
"Bring me a crystal from the Singing Vein — I will build something.":"Dalhan mo ako ng kristal mula sa Umaawit na Ugat — may bubuuin ako.",
"Our pilot is down, {0}. Get him out.":"Nabagsak ang piloto natin, {0}. Ilabas mo siya.",
"Destroy the enemy AA radar":"Wasakin ang AA radar ng kaaway",
"Carry the crystal to your base or point":"Dalhin ang kristal sa base mo o punto",
"A crystal from the Singing Vein":"Kristal mula sa Umaawit na Ugat",
"Rescue downed pilot \"{0}\"":"Iligtas ang bumagsak na piloto \"{0}\"",
"+3 CP, +150 ore":"+3 PP, +150 mineral",
