"Capture the relay":"Sakupin ang relay",
"HQ: the front is stuck. There is a chance — {0}.":"HQ: natigil ang prente. May pagkakataon — {0}.",
"HQ: the front is stuck — an op is available":"HQ: natigil ang prente — may magagawang operasyon",
"enemy turrets silent for 2 min":"tahimik ang mga turret ng kaaway nang 2 min",
"enemy map revealed for 60 s":"nakikita ang mapa ng kaaway nang 60 s",
"Generator destroyed":"Sumabog ang generator",
"Relay captured":"Atin na ang relay",
"Enemy generator down! Their turrets are silent for two minutes.":"Sumabog ang generator ng kaaway! Tahimik ang mga turret nila nang dalawang minuto.",
"The relay is ours! The whole enemy map is visible for a minute.":"Atin na ang relay! Kita ang buong mapa ng kaaway sa loob ng isang minuto.",
"Enemy sabotage: our turrets are down for 2 min":"Sabotahe ng kaaway: patay ang mga turret natin nang 2 min",
"Enemy took the relay: they see us for 60 s":"Kinuha ng kaaway ang relay: nakikita nila tayo nang 60 s",
"Sabotage! Our turrets are without power for two minutes.":"Sabotahe! Walang kuryente ang mga turret natin nang dalawang minuto.",
"The enemy took the relay — they see our whole map.":"Kinuha ng kaaway ang relay — nakikita nila ang buong mapa natin.",
"Intel: the enemy is going for our generator":"Intel: papunta ang kaaway para pasabugin ang generator natin",
