"thanks, back to building!":"salamat, tatapusin ko na ang pagtatayo!",
"thanks, we owe you!":"salamat, may utang kami sa iyo!",
"take the second gun — let us ride":"sumakay ka sa pangalawang baril — sasakay tayo",
"radar down! +3 CP, +150 ore":"bagsak na ang radar! +3 PU, +150 mineral",
"You have the crystal — carry it to the base or your point":"Nasa iyo ang kristal — dalhin sa base o sa punto mo",
"what a crystal! Here is an artifact and +2 CP":"ang ganda ng kristal! Heto ang artifact at +2 PU",
"Pilot \"{0}\" rescued{1}":"Nailigtas ang piloto \"{0}\"{1}",
"Thanks, guys! Grabbing a rifle — I am with you.":"Salamat, mga kasama! Kukuha ako ng riple — kasama ninyo ako.",
"hero quest":"quest ng bayani",
"here, a gun from the trunk — MG for 90 s":"heto, baril mula sa likod ng sasakyan — MG nang 90 s",
"a pod is launched from the base — a trooper for your squad":"may kapsulang paparating mula sa base — sundalo para sa iskuwad mo",
"a satellite will cover you for 20 s":"tatakpan ka ng satellite nang 20 s",
"+2 CP for HQ":"+2 PU para sa HQ",
"Pod from the base: {0} joins the squad":"Kapsula mula sa base: sumali sa iskuwad si {0}",
"Living world: your units ask for help, heroes give quests. Card on the right — ✕ to dismiss.":"Buhay na mundo: humihingi ng tulong ang mga sarili mong unit, nagbibigay ng quest ang mga bayani. Card sa kanan — ✕ para alisin.",
"Living world: your units ask for help, heroes give quests. Y — accept, N — decline.":"Buhay na mundo: humihingi ng tulong ang mga sarili mong unit, nagbibigay ng quest ang mga bayani. Y — tanggapin, N — tanggihan.",
