"Request skipped":"Nilaktawan ang hiling",
"Quest dropped":"Kinansela ang quest",
"HELP":"TULONG",
"GENERATOR":"GENERATOR",
"RELAY":"RELAY",
"SABOTAGE":"SABOTAHE",
"Living world: requests, hero quests, breakthrough ops":"Buhay na mundo: mga hiling, quest ng bayani, operasyon sa laban",
"Living world":"Buhay na mundo",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Humihingi ng tulong ang mga sarili mong unit at nagbibigay ng gantimpala, nagbibigay ng quest ang mga bayani, at binabasag ang natigil na prente sa pamamagitan ng operasyon",
"A request":"Hiling ng sarili",
"Breakthrough":"Pagbuwag sa prente",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Paminsan-minsang humihingi ng tulong ang mga sarili mong unit: boses sa radyo, card na HILING at markang ✋. Naipit ang isang iskuwad — wasakin ang mga kaaway sa tabi nito. Gantimpala: sundalo sa kapsula mula sa base, baril mula sa likod ng buggy, upuan ng gunner o takip mula sa orbit. Hindi ngayon — ✕ o huwag na lang pansinin.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ang beteranong tiktik na \"Kuwago\" ay may alok na quest. Y — tanggapin (N — tanggihan). Pumunta sa markang ★, tanggalin ang bantay at tumayo sa tabi ng piloto nang 3 s — sasama siya sa iskuwad mo.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Natigil ang prente — nag-aalok ang HQ ng pagbuwag sa prente. Y — tanggapin. Hawakan ang relay nang 8 s nang walang kaaway sa malapit: makikita ang mapa ng kaaway nang 60 s. Ang generator — tatahimik ang mga turret ng kaaway nang 2 min. Sa Strategist — \"Italaga sa iskuwad\". Magagawa rin ito ng kaaway: bantayan ang ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Humihingi ng tulong ang mga sarili mong unit: card na HILING at markang ✋. Wasakin ang mga kaaway malapit sa naipit na iskuwad — makakakuha ka ng gantimpala. ✕ — laktawan.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"May alok na quest ang bayaning \"Kuwago\" — i-tap ang \"Tanggapin\". Pumunta sa ★, tanggalin ang bantay, tumayo sa tabi ng piloto.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Natigil ang prente — i-tap ang \"Tanggapin\" at hawakan ang relay nang 8 s: bubukas ang mapa ng kaaway nang isang minuto.",
"Pod redeploy from the base: {0} m — through the sky portal":"Paglilipat sa pamamagitan ng kapsula mula sa base: {0} m — sa pamamagitan ng portal sa kalangitan",
"Pod away from the base! Hold on — exit over the target.":"Umalis na ang kapsula mula sa base! Kumapit — lalabas sa ibabaw ng target.",
"Landed at the objective!":"Nakalapag sa layunin!",
"LAUNCH FROM BASE":"LUNSAD MULA SA BASE",
"LANDING":"PAGLAPAG",
"REDEPLOY":"PAGLILIPAT",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Dumikit ang Himulmol na Bakal — kinakain ang armor −2/s. Tumayo nang 3 s sa labas ng laban o humanap ng inhinyero",
"An engineer brushed the fluff off":"Nilinis ng inhinyero ang himulmol",
"The fluff fell off — armour is safe":"Nalaglag ang himulmol — ligtas ang armor",
"The firefly swarm scattered by the blast":"Nagkawatak-watak ang Kawan ng Alitaptap dahil sa pagsabog",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"HIMULMOL NA BAKAL −2/s · tumayo nang 3 s o humanap ng inhinyero",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Handa na ang convoy ni Kaliwete: dalawang \"Chacal\". Manatiling malapit — hinihintay ka nila",
"The convoy is waiting for you":"Hinihintay ka ng convoy",
"Ambush! Cover the Jackals!":"Ambush! Protektahan ang mga \"Chacal\"!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"nakarating ang convoy ({0} sa 2)! +2 PU, +150 mineral, sa iyo na ang mga \"Chacal\"",
"The parts are delivered! Thanks, commander.":"Nandito na ang mga piyesa! Salamat, komandante.",
"Show tips again":"Ipakita ulit ang mga tip",
"Reset":"I-reset",
"Sure? Tap again":"Sigurado ka? Tap ulit",
"Done":"Tapos na",
