"Steel fluff":"Himulmol na Bakal",
"Rootwalker":"Lakad-Ugat",
"Firefly swarm":"Kawan ng Alitaptap",
"Steel dandelions — Steel fluff! It sticks and eats armour!":"Mga bakal na dandelion — Himulmol na Bakal! Kumakapit at kumakain ng armor!",
"Fluff in the air — keep out of the meadow and away from the infected!":"Lumilipad ang himulmol — huwag pumasok sa parang, at huwag dumikit sa mga nahawaan!",
"fluff blown away, dormant for 25 s · +0.5 CP":"nawala ang himulmol, tulog ang parang sa loob ng 25 s · +0.5 PU",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Dinadala ng mga tauhan ko ang mga piyesa sa punto {0}. Bantayan mo ang hanay — baka may nakaabang sa daan.",
