"Repairs others":"Nagkukumpuni ng iba",
"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Nagtatayo ng mga gusali at Extractor, nagkukumpuni, nagtatanggal ng Himulmol na Bakal sa iba.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Lumilipad ang iskuwad mula sa launch pad ng base, sa portal sa kalangitan, diretso sa target.",
"Squad: ":"Iskuwad: ",
